const lead = $input.first().json.body ?? $input.first().json;
const required = ['company_name', 'source_url', 'contact_basis'];
const missing = required.filter((key) => !String(lead[key] ?? '').trim());
let sourceUrl = null;
try { sourceUrl = new URL(String(lead.source_url ?? '').trim()); } catch {}
if (sourceUrl && !['http:', 'https:'].includes(sourceUrl.protocol)) sourceUrl = null;
const errors = [...missing];
if (!sourceUrl) errors.push('source_url must be a valid HTTP or HTTPS URL');
return [{ json: {
  ...lead,
  company_name: String(lead.company_name ?? '').trim().slice(0, 240),
  contact_email: String(lead.contact_email ?? '').trim().slice(0, 254),
  telegram_chat_id: String(lead.telegram_chat_id ?? '').trim().slice(0, 100),
  product_or_order_signal: String(lead.product_or_order_signal ?? '').trim().slice(0, 1000),
  source_url: sourceUrl ? sourceUrl.toString().slice(0, 2000) : String(lead.source_url ?? '').trim().slice(0, 2000),
  _lead_valid: errors.length === 0,
  _validation_errors: errors
} }];

const lead = $input.first().json;
if (lead._lead_valid !== true || !String(lead.contact_email ?? '').trim()) return [];
return [{ json: lead }];

const lead = $input.first().json;
const approved = lead.outreach_approved === true && lead.opt_in === true;
const hasChat = Boolean(String(lead.telegram_chat_id ?? '').trim());
if (lead._lead_valid !== true || !approved || !hasChat) return [];
return [{ json: lead }];
